package io.github.diodeme.ji.telemetry;

import java.util.Objects;
import java.util.concurrent.CompletionStage;
import java.util.function.Function;

final class SafeTelemetryContext implements TelemetryContext {
    private final TelemetrySink sink;
    private final SpanParent parent;

    SafeTelemetryContext(TelemetrySink sink, SpanParent parent) {
        this.sink = sink;
        this.parent = parent;
    }

    @Override
    public <T> T inSpan(SpanSpec spec, Function<TelemetrySpan, T> callback) {
        Objects.requireNonNull(callback, "callback");
        TelemetrySpan span = createSpan(spec);
        try {
            T value = callback.apply(span);
            span.settle(false);
            return value;
        } catch (Throwable failure) {
            span.settle(true);
            throw failure;
        }
    }

    @Override
    public <T> CompletionStage<T> inSpanAsync(SpanSpec spec, Function<TelemetrySpan, CompletionStage<T>> callback) {
        Objects.requireNonNull(callback, "callback");
        TelemetrySpan span = createSpan(spec);
        final CompletionStage<T> stage;
        try {
            stage = callback.apply(span);
        } catch (Throwable failure) {
            span.settle(true);
            throw failure;
        }
        if (stage == null) {
            span.settle(true);
            throw new NullPointerException("telemetry callback returned null CompletionStage");
        }
        return stage.whenComplete((value, failure) -> span.settle(failure != null));
    }

    private TelemetrySpan createSpan(SpanSpec spec) {
        try {
            TelemetrySpan created = sink.start(parent, spec);
            return new GuardedTelemetrySpan(sink, created);
        } catch (Throwable ignored) {
            return NoopTelemetryContext.INSTANCE;
        }
    }
}
